import Foundation
import AppKit
import AVFoundation

@main struct StateTests {
    @MainActor static func main() async throws {
        let directory=URL(fileURLWithPath:"/tmp/sovereign-tests-"+UUID().uuidString)
        let s=AppStore(directory:directory,simulation:.init(timeScale:0.01))
        var assertions=0
        func check(_ value: @autoclosure ()->Bool,_ title:String){assertions += 1;if !value(){print("FAIL: \(title)");exit(1)};print("PASS: \(title)")}
        func wait(_ ms:Int) async {try? await Task.sleep(for:.milliseconds(ms))}
        check(s.state.selected == [.chat],"Chat selected by default")
        check(abs(s.total-2.4)<0.001,"Initial total")
        s.next();check(s.state.step==1,"Welcome to capability selection")
        s.toggle(.voice);s.toggle(.images);s.toggle(.video);check(abs(s.total-20.9)<0.001,"All capability total 20.9 GB")
        s.toggle(.chat);check(s.state.selected.contains(.chat),"Chat remains selected")
        s.setHardware(.everyday);check(!s.available(.video) && !s.state.selected.contains(.video),"Everyday Mac makes Video unavailable")
        s.toggle(.video);check(s.error?.contains("memory")==true,"Unavailable Video explains why")
        s.error=nil;s.setHardware(.capable);s.toggle(.video);s.next();check(s.state.step==2,"Dedicated Evil reveal")
        s.chooseEvil(true);check(s.state.step==3 && s.state.evilEnabled && s.state.defaultMode == .evil,"Evil choice starts preparation")
        await wait(10);s.pausePreparation(.video);let paused=s.state.preparations["Video"]!.progress
        await wait(30);check(s.state.preparations["Video"]!.progress==paused,"Pause freezes progress")
        s.resumePreparation(.video);await wait(12);check(s.state.preparations["Video"]!.progress>paused,"Resume advances same job")
        s.cancelPreparation(.images);await wait(20);check(s.state.preparations["Images"]!.status == .cancelled,"Cancelled preparation cannot finish later")
        s.failPreparation=true;s.resumePreparation(.images);await wait(10);check(s.state.preparations["Images"]!.status == .failed,"Deterministic preparation failure")
        s.retryPreparation(.images);await wait(25);check(s.chatReady,"Chat becomes ready before optional work")
        s.enterChat();check(s.state.onboardingComplete && s.current?.mode == .evil,"Early entry inherits Evil Mode")
        s.setMode(.safe);let safeID=s.current!.id;s.newChat();check(s.current?.mode == .safe && s.state.evilEnabled,"New conversation starts Safe, reveal choice remains available")
        s.setMode(.evil);let evilChat=s.current!.id;s.state.appearance="Light";let clean=s.newChat();check(s.current?.mode == .safe && s.state.chats.first{$0.id==evilChat}?.mode == .evil,"Evil Mode belongs to one chat; new chat remains Safe")
        check(s.state.appearance=="Light","Per-chat mode does not change appearance")
        s.delete(clean)
        s.select(safeID);s.setDraft("Write a product idea");s.send();await wait(6)
        let switched=s.newChat();await wait(900)
        check(s.current?.id==switched && s.current?.messages.isEmpty==true,"Switching chat does not move response")
        check(s.state.chats.first{$0.id==safeID}!.messages.last?.status=="complete","Response finishes in owning conversation")
        s.select(safeID);s.setDraft("Another thought");s.send();await wait(4);s.stop(safeID);let stopped=s.current!.messages.last!.text;await wait(30);check(s.current!.messages.last!.text==stopped && s.current!.messages.last!.status=="stopped","Stop preserves partial output and cancels completion")
        let original=s.current!.messages.first{$0.role=="user"}!;s.editMessage(original,text:"Plan a weekend by the sea");await wait(900);check(s.current!.messages.count==2 && s.current!.messages.first!.text.contains("weekend"),"Edit replaces subsequent branch")
        let oldResponse=s.current!.messages.last!.id;s.regenerate(s.current!.messages.last!);await wait(900);check(s.current!.messages.count==2 && s.current!.messages.last!.id != oldResponse,"Regenerate replaces reply")
        s.rename(safeID,"Coastal notebook");s.search="Coastal";check(s.filteredChats.count==1,"Rename and search real chats")
        s.search="";s.state.preparations["Images"]=Preparation(progress:1,status:.ready);s.state.preparations["Video"]=Preparation(progress:1,status:.ready)
        s.setDraft("Create an image of a cliff house");s.send();await wait(250);let source=s.current!.messages.last!.artifact!;check(source.version==1 && source.parentID==nil,"Image creates original artifact")
        s.editArtifact(source,prompt:"Make the scene warmer");await wait(250);let edit=s.current!.messages.last!.artifact!;check(edit.id != source.id && edit.parentID==source.id && edit.version==2,"Image edit preserves original and creates associated version")
        s.setDraft("Create a video clip");s.send();await wait(250);let video=s.current!.messages.last!.artifact!;s.editArtifact(video,prompt:"Trim this scene",trim:(1,4.5));await wait(250);let trim=s.current!.messages.last!.artifact!;check(trim.parentID==video.id && trim.trimStart==1 && trim.trimEnd==4.5,"Video trim is a distinct artifact draft version")
        s.failNextResponse=true;s.editArtifact(source,prompt:"Try another atmosphere");await wait(250);check(s.current!.messages.last!.status=="failed","Media failure repeatable")
        let failedEdit=s.current!.messages.last!;s.regenerate(failedEdit);await wait(250);check(s.current!.messages.last!.artifact?.parentID==source.id && s.current!.messages.last!.artifact?.version==2,"Retry preserves edit source association")
        s.setDraft("Create an image");s.send();await wait(5);s.stop(safeID);let count=s.current!.messages.count;await wait(250);check(s.current!.messages.count==count && s.current!.messages.last!.artifact==nil,"Media cancellation has no delayed artifact")
        s.consent = .gmail;s.consent=nil;check(s.state.connections["Gmail"]==nil,"Consent cancel grants nothing")
        s.connect(.gmail);check(s.state.connections["Gmail"] == .connected,"Consent connects shared state")
        s.expireConnection();check(s.state.connections["Gmail"] == .expired,"Connection can expire")
        s.connect(.gmail);s.disconnect(.gmail);check(s.state.connections["Gmail"] == .disconnected,"Reconnect and disconnect")
        s.setDraft("Keep my draft\nwith a new line");s.addDemoAttachment();s.select(switched);s.select(safeID);check(s.current!.draft.contains("\n") && s.current!.attachments.count==1,"Drafts and attachments survive conversation switches")
        s.dictate();await wait(50);check(s.current!.draft.contains("calm, creative"),"Dictation inserts editable sample transcript")
        let unsupported=directory.appendingPathComponent("example.exe");try Data([1,2]).write(to:unsupported);s.importAttachment(unsupported);check(s.error?.contains("isn't supported")==true,"Unsupported attachment preserves draft")
        s.state.appearance="Dark";s.setMode(.evil);s.save();let reloaded=AppStore(directory:directory,simulation:.init(timeScale:0.01));check(reloaded.current?.draft==s.current?.draft && reloaded.current?.attachments==s.current?.attachments,"Persistence restores drafts and attachments")
        check(reloaded.current?.mode == .evil && reloaded.state.appearance=="Dark" && reloaded.state.onboardingComplete,"Persistence restores mode, appearance and onboarding")
        check(reloaded.state.chats.count==s.state.chats.count,"Samples are seeded only once")
        s.setDraft("Hello");s.send();s.save();let interrupted=AppStore(directory:directory);check(interrupted.current?.messages.last!.status=="stopped","Interrupted responses recover as stopped")
        s.stop(safeID);s.delete(safeID);await wait(40);check(!s.state.chats.contains{$0.id==safeID},"Delete cancels owned work")
        s.restartOnboarding();s.next();s.next();s.chooseEvil(false);check(s.state.defaultMode == .safe,"Safe choice works on repeated walkthrough")
        s.back();s.back();check(s.state.step==1 && s.state.selected.contains(.images),"Back navigation preserves selections")
        let low=AppStore(directory:directory.appendingPathComponent("low"),simulation:.init(timeScale:0.01));low.setHardware(.storage);low.toggle(.voice);low.toggle(.video);check(!low.available(.voice) && !low.state.selected.contains(.voice) && !low.state.selected.contains(.video) && low.error?.contains("space")==true,"Low storage blocks Voice and Video before preparation")
        low.chooseEvil(false);await wait(300);check(low.chatReady && low.state.preparations["Voice"]?.status != .failed,"Low storage prepares Chat without a later space failure")
        low.setHardware(.capable);low.toggle(.video);low.resumePreparation(.video);await wait(700);check(low.state.preparations["Video"]?.status == .ready,"Video can be prepared once space is available")
        check(s.simulation.response(to:"weekend",mode:.safe) != s.simulation.response(to:"weekend",mode:.evil),"Safe and Evil use distinct response style")
        s.voice.open();s.voice.sampleTurn();s.voice.interrupt();await wait(30);check(s.voice.phase=="Listening" && (s.voice.audio?.rate ?? 0)==0,"Voice interrupt cancels pending speech")
        s.voice.toggleMute();check(s.voice.muted && s.voice.phase=="Muted","Voice mute has visible state")
        s.voice.end();check(!s.voice.isOpen && (s.voice.audio?.rate ?? 0)==0,"Voice end stops audio")
        let skill=SkillRecord(name:"Concise answers",instructions:"Keep answers concise and use bullet points.")
        s.saveSkill(skill);check(s.skills.count==1 && s.skills[0].isEnabled,"Add an enabled local skill")
        var updated=skill;updated.name="Brief bullets";s.saveSkill(updated);check(s.skills.count==1 && s.skills[0].name=="Brief bullets","Editing skill updates stable identity")
        s.setSkillEnabled(skill.id,false);check(!s.skills[0].isEnabled,"Disable skill")
        s.setSkillEnabled(skill.id,true)
        let styled=s.simulation.applySkills(to:s.simulation.response(to:"product idea",mode:.safe),skills:s.skills)
        check(styled.hasPrefix("• ") && styled.count<500,"Enabled concise/bullet skill affects simulated reply")
        let file=directory.appendingPathComponent("writing.md");try "# Writing style\nUse bullet points.".write(to:file,atomically:true,encoding:.utf8);s.importSkillFile(file);check(s.skills.count==2 && s.skills.last?.name=="Writing style","Import Markdown skill")
        s.state.fileReadingEnabled=false;s.addDemoAttachment();check(s.error?.contains("Read attachments")==true,"Disabled attachment tool blocks new file access")
        s.state.webSearch=true;s.save();let skillsRestored=AppStore(directory:directory);check(skillsRestored.skills==s.skills && skillsRestored.state.webSearch && skillsRestored.state.fileReadingEnabled==false,"Skills and tool choices persist")
        s.deleteSkill(skill.id);check(s.skills.count==1 && s.skills[0].name=="Writing style","Delete one skill without removing another")
        check(s.macSpecs.memoryGB>0 && s.macSpecs.freeStorageGB>=0,"Hardware summary reads actual memory and free storage")
        print("\n\(assertions) checks passed.")
    }
}
